from pathlib import Path
p=Path('index.html')
s=p.read_text(encoding='utf-8')
old_start='/* =========================\n   FORMAL PORTFOLIO INTRO\n========================= */'
start=s.find(old_start)
if start==-1:
    raise SystemExit('intro CSS start not found')
end=s.find('</style>', start)
if end==-1:
    raise SystemExit('intro CSS end not found')
new_css='''/* =========================\n   FUTURISTIC PORTFOLIO INTRO\n========================= */\n\n#portfolio-intro{position:fixed;inset:0;z-index:99999;display:flex;align-items:center;justify-content:center;overflow:hidden;background:#03050a;opacity:1;visibility:visible;transition:opacity .9s ease,visibility .9s ease}\n#portfolio-intro.hide{opacity:0;visibility:hidden;pointer-events:none}\n#portfolio-intro::before{content:"";position:absolute;inset:0;background-image:linear-gradient(rgba(103,232,249,.045) 1px,transparent 1px),linear-gradient(90deg,rgba(103,232,249,.045) 1px,transparent 1px);background-size:42px 42px;mask-image:radial-gradient(circle at center,#000 0%,rgba(0,0,0,.75) 38%,transparent 78%);animation:introGrid 10s linear infinite}\n#portfolio-intro::after{content:"";position:absolute;width:42vw;height:42vw;max-width:560px;max-height:560px;min-width:300px;min-height:300px;border-radius:50%;border:1px solid rgba(103,232,249,.12);box-shadow:0 0 90px rgba(90,167,255,.08),inset 0 0 90px rgba(90,167,255,.05);animation:introOrbit 12s linear infinite}\n.intro-content{position:relative;z-index:2;text-align:center;font-family:"Space Grotesk",Inter,sans-serif;color:#fff;animation:introContent .9s cubic-bezier(.16,1,.3,1) both}\n.intro-content::before,.intro-content::after{content:"";position:absolute;top:50%;width:clamp(45px,9vw,130px);height:1px;background:linear-gradient(90deg,transparent,rgba(103,232,249,.75));transform:translateY(-50%)}\n.intro-content::before{right:calc(100% + 28px)}\n.intro-content::after{left:calc(100% + 28px);transform:translateY(-50%) rotate(180deg)}\n.intro-first{font-size:clamp(46px,7vw,94px);line-height:.9;font-weight:600;letter-spacing:.19em;margin-left:.19em;text-shadow:0 0 30px rgba(117,246,255,.12)}\n.intro-last{margin-top:12px;font-size:clamp(17px,2.3vw,31px);line-height:1;font-weight:400;letter-spacing:.5em;margin-left:.5em;color:#75f6ff;text-shadow:0 0 22px rgba(117,246,255,.2)}\n.intro-line{position:relative;width:clamp(90px,12vw,150px);height:1px;margin:27px auto 0;overflow:hidden;background:rgba(117,246,255,.14)}\n.intro-line::after{content:"";position:absolute;inset:0;background:linear-gradient(90deg,transparent,#75f6ff,transparent);transform:translateX(-100%);animation:introScan 1.1s ease .75s forwards}\n.intro-meta{margin-top:14px;font:9px "DM Mono",monospace;letter-spacing:.18em;color:rgba(135,147,167,.75);text-transform:uppercase}\n@keyframes introContent{from{opacity:0;transform:translateY(12px) scale(.98);filter:blur(6px)}to{opacity:1;transform:none;filter:blur(0)}}\n@keyframes introGrid{from{background-position:0 0}to{background-position:42px 42px}}\n@keyframes introOrbit{from{transform:rotate(0deg) scale(.94)}50%{transform:rotate(180deg) scale(1.02)}to{transform:rotate(360deg) scale(.94)}}\n@keyframes introScan{to{transform:translateX(100%)}}\n@media(max-width:600px){.intro-first{letter-spacing:.12em;margin-left:.12em}.intro-last{letter-spacing:.28em;margin-left:.28em}.intro-content::before{right:calc(100% + 14px)}.intro-content::after{left:calc(100% + 14px)}}\n@media(prefers-reduced-motion:reduce){#portfolio-intro::before,#portfolio-intro::after,.intro-content,.intro-line::after{animation:none!important}}\n'''
s=s[:start]+new_css+s[end:]
s=s.replace('        <div class="intro-line"></div>','        <div class="intro-line"></div>\n        <div class="intro-meta">SOFTWARE · AI · ELECTRONICS</div>',1)
old_js='''<script>\nwindow.addEventListener("load", () => {\n\n    setTimeout(() => {\n\n        document\n            .getElementById("portfolio-intro")\n            .classList.add("hide");\n\n    }, 2200);\n\n});\n</script>'''
new_js='''<script>\nwindow.addEventListener("load", () => {\n    const intro = document.getElementById("portfolio-intro");\n    if (!intro) return;\n    setTimeout(() => {\n        intro.classList.add("hide");\n    }, 2600);\n});\n</script>'''
if old_js in s:
    s=s.replace(old_js,new_js,1)
else:
    s=s.replace('</body>', '<script>window.addEventListener("load",()=>{const intro=document.getElementById("portfolio-intro");if(intro)setTimeout(()=>intro.classList.add("hide"),2600);});</script>\n</body>',1)
p.write_text(s,encoding='utf-8')
